        public async Task< string> Linkmahdodaytmoalfeh(List<dbtarifmahdodayt6> modelList)
        {
            List<dbtarifmahdodayt6> dbtarifmahdodayt6 = new List<dbtarifmahdodayt6>();
            using (var context = new SaabEntities())
            {
                var find34 = context.dbtarifmahdodayt6.ToList();

                foreach (var it in modelList)
                {
                    var find = find34.Where(p => p.FK_moalfeh == it.FK_moalfeh && p.FK_name == it.FK_name).FirstOrDefault();
                    if (find != null)
                    {
                        if (find.value != it.value)
                        {
                            find.value = it.value;
                            //context.SaveChanges();
                        }


                    }
                    else
                    {
                        context.dbtarifmahdodayt6.Add(it);
                        //context.SaveChanges();
                    }
                }
                await context.SaveChangesAsync();

                return "true";
            }
        }

        public string UpdateRecordmahedit2(List<tbmarahlsabtbastedit2> modelList)
