        public ActionResult creatmahddatcount(int taeed = 0, int marahelsabt = 0, int createmarhaleh1 = 0)
        {
            var find = db.tbmarhesabt3.Where(p => p.marahelsabt != null).FirstOrDefault();
            if (find != null)
            {
                find.taeed = taeed;
                find.marahelsabt = marahelsabt;
                find.controlmarahel = createmarhaleh1;
                db.SaveChanges();

            }
            else
            {
                tbmarhesabt3 tbmarhesabt3 = new tbmarhesabt3();
                tbmarhesabt3.taeed = taeed;
                tbmarhesabt3.marahelsabt = marahelsabt;
                tbmarhesabt3.controlmarahel = createmarhaleh1;
                db.tbmarhesabt3.Add(tbmarhesabt3);
                db.SaveChanges();
            }
            return Content("True");

        }
        public string GetDataFromExcel_FishtAEAD(HttpPostedFileBase MyExcelStream, int Basteh)
        {
            int mlfvlfsh_Year, mlfvlfsh_Month, malefe;
            float mlfvlfsh_Value;
            int id = 0;
            string name = "";
            var moalf = db.tbContractMoalefeDastmozdi.ToList();
            List<tbmarahelsabt2> IsFish = new List<tbmarahelsabt2>();
            var workbook = Telerik.Web.Spreadsheet.Workbook.Load(MyExcelStream.InputStream, System.IO.Path.GetExtension(MyExcelStream.FileName));
            using (DbContextTransaction transaction = db.Database.BeginTransaction())
            {
                try
                {
                    var Count_Sheets = workbook.Sheets.Count;
                    if (Count_Sheets >= 1)
                    {
                        var sheet = workbook.Sheets[0];
                        var Rows = sheet.Rows;
                        if (Rows.Count >= 1)
                        {
                            foreach (var item in Rows)
                            {
                                if (item.Cells.Count != sheet.Rows[0].Cells.Count)
                                {
                                    return " خطای ارزیابی در سطر " + (item.Index + 1).ToString() + " رخ داده است. یکی از سلول های این ستون فاقد اطلاعات می باشد ";
                                    ;
                                }
                                var title = workbook.Sheets[0].Rows[0].Cells;
                                var List = workbook.Sheets[0].Rows;
                                var count = workbook.Sheets[0].Rows.Count();
                                if (count == 1)
                                {
                                    return "فایل اکسل فاقد اطلاعات می باشد";
                                }
                                var list = db.tbmarahelsabt2.Where(p => p.FK_name == Basteh && p.del != true).ToList();
                                foreach (var it in list)
                                {
                                    it.del = true;
                                    db.SaveChanges();
                                }
                                for (int i = 1; i < count; i++)
                                {
                                    var row = workbook.Sheets[0].Rows[i];
                                    var Name = row.Cells[0];
                                    if (int.TryParse(Name.Value.ToString(), out int result))
                                    {
                                        id = result;
                                    } // Assuming Name.Value is convertible to an integer.                                    }
                                    else
                                    {
                                        return " لطفا ستون نام  سطر " + " ( " + i + " ) " + "را پر کنید ";
                                    }

                                    //var c2 = moalf.Where(p => p.md_ID==id).FirstOrDefault();

                                    tbmarahelsabt2 tbm = new tbmarahelsabt2();
                                    tbm.FK_name = Basteh;
                                    tbm.FK_moalfe = id;
                                    IsFish.Add(tbm);






                                }
                                db.tbmarahelsabt2.AddRange(IsFish);
                                db.SaveChanges();
                                break;
                            }
                        }
                        else
                        {
                            return "این شیت فاقد سطر می باشد";
                        }
                    }
                    else
                    {
                        return "هیچ شیتی در این اکسل وجود ندارد";
                    }
                    transaction.Commit();
                    return "با موفقیت انجام شد";
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    return ex.Message;

                }
            }
        }
