        public async Task<ActionResult> viewmonthyearmahdodat2()
        {


            var tbmoalfefishexcel = db.tbmoalfefishexcel.ToList();
            var findyaer = db.tbFaalMahdod.Where(s => s.actiive == true).OrderByDescending(s => s.ID).FirstOrDefault();

            FunctionModel lstMoalefeexcel2 = new FunctionModel();
            lstMoalefeexcel2.tickmomahdodat = new List<tickmomahdodat>();
            int month = 1;
            int year = 1404;
            if (findyaer != null && findyaer.month != null && findyaer.Year != null)
            {
                month = (int)findyaer.month;
                year = (int)findyaer.Year;
            }
            //var tbdetail = new tbdetail
            //{
            //    tbmarahesabt4 = t.tbmarahesabt4,
            //    tbSavedFunctions = t,
            //    day = 1,
            //    month = month,
            //    year = year
            //};
            //lstMoalefeexcel2.tbdetail.Add(tbdetail);
            int usrID = 0;
            lstMoalefeexcel2.year = new year();
            var yer = new year();
            yer.MoalfeVal_Year = year;
            yer.month = month;
            lstMoalefeexcel2.year = yer;
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user != null)
            {
                var phone = Utility.Base64.Base64Decode(cookie_user.Value);


                var User = await db.tbUsers.Where(p => p.usr_NationalCode.ToString() == phone).FirstOrDefaultAsync();
                if (User != null)
                {
                    usrID = User.usr_ID;


                }
            }

            if (db.tbAdamShahr.Where(s => s.idkarbar == usrID && s.value == 1).FirstOrDefault() == null)
            {

                return View("~/Areas/Reporter/Views/Dashboard/_banner.cshtml");

            }
            else
            {
                var tarifList = db.dbtarifmahdodayt6
                       .Where(s => s.FK_name == usrID && s.value == true)
                       .ToList();

                // بارگذاری همه MoalefeValueFish های ماه و سال مورد نظر برای کاربر
                var allFish = db.tbmoalfefishexcel
                    .AsNoTracking() // برای سرعت بیشتر
                    .Where(p => p.FK_control != null && p.usr_sabt == usrID)
                    .SelectMany(p => p.tbMoalefeValueFish
                        .Where(s => s.mlfvlfsh_Month == month && s.mlfvlfsh_Year == year),
                        (p, s) => new {
                            MoalefeExcel = p,
                            Fish = s
                        })
                    .ToList();

                // دیکشنری برای دسترسی سریع با FK_Moalefe
                var fishDict = allFish
                    .GroupBy(x => x.Fish.FK_Moalefe)
                    .ToDictionary(g => g.Key, g => g.ToList());

                //var lstMoalefeexcel2 = new tickmomahdodat(); // مدل ویو شما

                foreach (var it in tarifList)
                {
                    int value = 0; // مقدار پیش فرض

                    if (fishDict.TryGetValue(it.FK_moalfeh, out var fishList))
                    {
                        var find2 = fishList.FirstOrDefault(s => s.Fish.submit == true);
                        var find = fishList.FirstOrDefault(s => s.Fish.submit != true);
                        var find3 = tbmoalfefishexcel.FirstOrDefault(p => p.sabtnahaei == true && fishList.Any(f => f.Fish.FK_Moalefe == it.FK_moalfeh));
                        var find4 = tbmoalfefishexcel.FirstOrDefault(p => p.sabtaval == true && p.sabt == 1 && fishList.Any(f => f.Fish.FK_Moalefe == it.FK_moalfeh));

                        if (find2 != null) value = 2;
                        else if (find != null) value = 1;
                        else if (find3 != null) value = 3;
                        else value = 0;
                    }

                    var tickmomahdodat = new tickmomahdodat
                    {
                        IDMOalfeh = (int)it.FK_moalfeh,
                        namemoalfeh = it.tbContractMoalefeDastmozdi.md_Title,
                        nomoalfeh = it.tbContractMoalefeDastmozdi.tbUnitParameter.unt_Name,
                        value = value,
                    };

                    lstMoalefeexcel2.tickmomahdodat.Add(tickmomahdodat);
                }

                return View("~/Areas/Contracts/Views/RegistrationAndConfirmationProcedures/viewmonthyearmahdodat.cshtml", lstMoalefeexcel2);
            
        }



        }
