        public async Task<ActionResult> viewmonthyearmahdodat()
        {
            int month = 1;
            int year = 1404;

            var findYear = await db.tbFaalMahdod
                .Where(s => s.actiive==true)
                .OrderByDescending(s => s.ID)
                .FirstOrDefaultAsync();

            if (findYear != null)
            {
                month = findYear.month ?? month;
                year = findYear.Year ?? year;
            }

            FunctionModel lstMoalefeexcel2 = new FunctionModel
            {
                tickmomahdodat = new List<tickmomahdodat>(),
                year = new year { MoalfeVal_Year = year, month = month }
            };

            int usrID = 0;
            var cookieUser = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookieUser != null)
            {
                var phone = Utility.Base64.Base64Decode(cookieUser.Value);
                var user = await db.tbUsers.FirstOrDefaultAsync(p => p.usr_NationalCode.ToString() == phone);
                if (user != null) usrID = user.usr_ID;
            }

            bool hasAccess = await db.tbAdamShahr.AnyAsync(s => s.idkarbar == usrID && s.value == 1);
            if (!hasAccess)
                return View("~/Areas/Reporter/Views/Dashboard/_banner.cshtml");

            // دریافت لیست محدودیت‌های کاربر
            var userMahdods = await db.dbtarifmahdodayt6
                .Where(t => t.FK_name == usrID && t.value == true)
                .Select(t => new
                {
                    t.FK_moalfeh,
                    t.tbContractMoalefeDastmozdi.md_Title,
                    t.tbContractMoalefeDastmozdi.tbUnitParameter.unt_Name
                })
                .ToListAsync();

            // دریافت اطلاعات Moalefe برای ماه و سال
            var moalfeValues = await db.tbmoalfefishexcel
                .Where(m => m.usr_sabt == usrID)
                .Select(m => new
                {
                    m.ID,
                    m.sabtnahaei,
                    m.sabtaval,
                    m.sabt,
                    Values = m.tbMoalefeValueFish
                        .Where(f => f.mlfvlfsh_Month == month && f.mlfvlfsh_Year == year)
                        .Select(f => new { f.FK_Moalefe, f.submit })
                })
                .ToListAsync();

            foreach (var it in userMahdods)
            {
                int value = 0;

                var moalfe = moalfeValues
                    .FirstOrDefault(m => m.Values.Any(f => f.FK_Moalefe == it.FK_moalfeh));

                if (moalfe != null)
                {
                    var submitted = moalfe.Values.Any(f => f.FK_Moalefe == it.FK_moalfeh && f.submit==true);
                    if (submitted) value = 2;
                    else if (!submitted) value = 1;
                    else if (moalfe.sabtnahaei == true) value = 3;
                    else if (moalfe.sabtaval == true && moalfe.sabt == 1) value = 4;
                }

                lstMoalefeexcel2.tickmomahdodat.Add(new tickmomahdodat
                {
                    IDMOalfeh = (int)it.FK_moalfeh,
                    namemoalfeh = it.md_Title,
                    nomoalfeh = it.unt_Name,
                    value = value
                });
            }

            return View("~/Areas/Contracts/Views/RegistrationAndConfirmationProcedures/viewmonthyearmahdodat.cshtml", lstMoalefeexcel2);
        }

