        private string GetSqlConnectionString()
        {
            try
            {
                var entityConnection = new EntityConnection(
                    ConfigurationManager.ConnectionStrings["SaabEntities"].ConnectionString);

                return entityConnection.StoreConnection.ConnectionString;
            }
            catch
            {
                return "REPLACE_WITH_CONNECTION_STRING";
            }
        }

        public async Task<ActionResult> viewmonthyearmahdodatmahdodatasli1(int month = 0, int year = 0, int id = 0)
        {
            try
            {
                if (month == 0)
                {
                    month = 11;
                    year = 1403;
                }

                int mainUserId = 0;

                // گرفتن یوزر از کوکی
                var cookie = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie != null)
                {
                    var code = Utility.Base64.Base64Decode(cookie.Value);
                    var u = await db.tbUsers.FirstOrDefaultAsync(x => x.usr_NationalCode.ToString() == code);
                    if (u != null) mainUserId = u.usr_ID;
                }

                if (mainUserId == 0)
                    return Content("user not found");

                // پیدا کردن FK_moalfe
                var findjpb = db.tbmarahlsabtbastedit6.FirstOrDefault(p => p.FK_moalfeh2 == id);
                int idd = findjpb != null ? System.Convert.ToInt32(findjpb.FK_moalfe) : id;

                // SQL با پارامترها
                string sql = @"
SELECT 
    u.usr_ID,

    u.usr_Personal_ID,
    c.Name AS CityName,
    c.ID AS CityID,
    t4.FK_name AS BastehID,
    t3.name AS BastehName,
    pc.ID AS PeymanID,
    pc.pec_Title AS PeymanName,
    ISNULL(t2.value,0) AS SeghfUser,
    ISNULL(t5.value,0) AS SeghfBasteh,
    ISNULL(mp.Moadel,0) AS Moadel,
    vf.mlfvlfsh_Value AS MoalefeValue
FROM dbo.tbAdamAdam aa
JOIN Usser.tbUsers u ON u.usr_ID = aa.nam
LEFT JOIN dbo.tbCities c ON c.ID = u.usr_City_Dutysystem
LEFT JOIN Contract.Link_User_And_Peyman lup ON lup.FK_User_ID = u.usr_ID AND lup.Status=1
LEFT JOIN Contract.tbPeymanContracts pc ON pc.ID = lup.FK_Peyman_ID
LEFT JOIN Salary.dbtarifmahdodayt4 t4 ON t4.FK_usr=u.usr_ID AND t4.Position=1
LEFT JOIN Salary.dbtarifmahdodayt3 t3 ON t3.ID=t4.FK_name
LEFT JOIN Salary.dbtarifmahdodayt2 t2 ON t2.FK_usr=u.usr_ID AND t2.FK_moalfe=@mid
LEFT JOIN Salary.dbtarifmahdodayt5 t5 ON t5.FK_marhal4=t4.FK_name 
      AND t5.FK_city=u.usr_City_Dutysystem 
      AND t5.FK_Pymn=lup.FK_Peyman_ID 
      AND t5.FK_moalf=@mid
LEFT JOIN Salary.tbMoadelPadashJarimeAyab mp ON mp.UserID=u.usr_ID AND mp.Month=@month AND mp.Year=@year
LEFT JOIN Salary.tbMoalefeValueFish vf ON vf.FK_User=u.usr_ID AND vf.FK_Moalefe=@mid AND vf.mlfvlfsh_Month=@month AND vf.mlfvlfsh_Year=@year
WHERE aa.Name=@main AND aa.Value=1
";

                var parameters = new[]
                {
            new SqlParameter("@month", month),
            new SqlParameter("@year", year),
            new SqlParameter("@mid", idd),
            new SqlParameter("@main", mainUserId)
        };

                var list = new List<mahdoday>();

                // گرفتن connection string از Web.config
                string connStr = ConfigurationManager.ConnectionStrings["SaabEntities"].ConnectionString;
                var builder = new System.Data.Entity.Core.EntityClient.EntityConnectionStringBuilder(connStr);
                string sqlConnStr = builder.ProviderConnectionString;
                using (var conn = new SqlConnection(GetSqlConnectionString()))

                {
                    conn.Open(); // بدون async
                    using (var cmd = new System.Data.SqlClient.SqlCommand(sql, conn))
                    {
                        cmd.Parameters.AddRange(parameters);

                        using (var reader = cmd.ExecuteReader()) // بدون async
                        {
                            while (reader.Read())
                            {
                                list.Add(new mahdoday
                                {
                                    IDpersonal = System.Convert.ToInt32(reader["usr_ID"]),
                                    //fullnam = reader["FullName"]?.ToString(),
                                    PersonalID = System.Convert.ToInt32(reader["usr_Personal_ID"]),
                                    CITynam = reader["CityName"]?.ToString(),
                                    cityID = reader["CityID"] != DBNull.Value ? System.Convert.ToInt32(reader["CityID"]) : 0,
                                    bastehID = reader["BastehID"] != DBNull.Value ? System.Convert.ToInt32(reader["BastehID"]) : 0,
                                    bastehname = reader["BastehName"]?.ToString(),
                                    PymnID = reader["PeymanID"] != DBNull.Value ? System.Convert.ToInt32(reader["PeymanID"]) : 0,
                                    pymanname = reader["PeymanName"]?.ToString(),
                                    seghf = System.Convert.ToInt32(reader["SeghfUser"]),
                                    seghfBasteh = System.Convert.ToInt32(reader["SeghfBasteh"]),
                                    moadel = System.Convert.ToDouble(reader["Moadel"]),
                                    value22 = reader["MoalefeValue"] != DBNull.Value ? System.Convert.ToDouble(reader["MoalefeValue"]) : 0,
                                    month = month,
                                    year = year,
                                    fkmoalfe = idd
                                });
                            }
                        }
                    }
                    conn.Close(); // بدون async
                }


                var model = new FunctionModel
                {
                    year = new year { month = month, MoalfeVal_Year = year },
                    mahdoday = list
                };

                model.namemoalfeh = await db.tbContractMoalefeDastmozdi
                    .Where(x => x.md_ID == idd)
                    .Select(x => x.md_Title)
                    .FirstOrDefaultAsync();

                return View("~/Areas/Contracts/Views/RegistrationAndConfirmationProcedures/viewmonthyearmahdodatmahdodatasli.cshtml", model);
            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }

