                                    mahdoday.value22 = valll.mlfvlfsh_Value ?? 0;
                            }

                            lstMoalefeexcel2.mahdoday.Add(mahdoday);
                        }
                    }
                }

                var dbtarifmahdodayt1321 = dbtarifmahdodayt1.FirstOrDefault(p => p.FK_moalfe == id);
                lstMoalefeexcel2.namemoalfeh = dbtarifmahdodayt1321?.tbContractMoalefeDastmozdi.md_Title;

                return View("~/Areas/Contracts/Views/RegistrationAndConfirmationProcedures/viewmonthyearmahdodatmahdodatasli.cshtml", lstMoalefeexcel2);
            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }

