                        nametackBasteh = tackNameVal,
                        seghfBasteh = seghfBastehVal,
                        seghfBastehID = seghfBastehIDVal,
                        seghf = seghfVal,      // این خط اضافه شد
                        moadel = moadelVal,
                        value22 = value22,
                        month = month,
                        year = year
                    });
                }

                model.namemoalfeh = tarif1?.Title;

                return View("~/Areas/Contracts/Views/RegistrationAndConfirmationProcedures/viewmonthyearmahdodatmahdodatasli.cshtml", model);
            }
            catch (Exception ex)
            {
                return Content(ex.ToString());
            }
        }

