        public async Task<ActionResult> viewmonthyearmahdodatmahdodataslicreate(List<Dictionary<string, object>> dataList)
        {
            if (dataList == null || !dataList.Any())
                return Json(new { success = false, message = "لیست داده‌ها خالی است." });

            int year = System.Convert.ToInt32(dataList[0]["Year"]);
            int month = System.Convert.ToInt32(dataList[0]["Month"]);

            // استخراج کاربر از کوکی
            int usr = 0;
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user != null)
            {
                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                usr = await db.tbUsers
                    .Where(p => p.usr_NationalCode.ToString() == nationalcode)
                    .Select(x => x.usr_ID)
                    .FirstOrDefaultAsync();
            }

            if (usr == 0)
                return Json(new { success = false, message = "کاربر یافت نشد." });

            using (SaabEntities db = new SaabEntities())
            {
                // ==== Preload داده‌های موجود ====
                var cityIds = dataList.Select(d => System.Convert.ToInt32(d["CityID"])).Distinct().ToList();
                var pymnIds = dataList.Select(d => System.Convert.ToInt32(d["PymnID"])).Distinct().ToList();

                var existingExcel = await db.tbmoalfefishexcel
                    .Where(p => p.usr_sabt == usr && p.del != true &&
                                cityIds.Contains(p.city ?? 0) &&
                                pymnIds.Contains(p.Fk_Pymn ?? 0) &&
                                p.FK_control == true)
                    .Include(p => p.tbMoalefeValueFish)
                    .ToListAsync();

                List<tbmoalfefishexcel> newExcels = new List<tbmoalfefishexcel>();
                List<tbMoalefeValueFish> newFishItems = new List<tbMoalefeValueFish>();

                // ==== ایجاد یا شناسایی رکوردهای Excel ====
                foreach (var item in dataList)
                {
                    int cityID = System.Convert.ToInt32(item["CityID"]);
                    int pymnID = System.Convert.ToInt32(item["PymnID"]);
                    int idPersonal = System.Convert.ToInt32(item["IDPersonal"]);
                    int fkMoalfe = System.Convert.ToInt32(item["FkMoalfe"]);
                    decimal value = System.Convert.ToDecimal(item["value"]);
                    int sabt = System.Convert.ToInt32(item["sabt"]);

                    // پیدا کردن رکورد موجود
                    var excel = existingExcel.FirstOrDefault(p => p.city == cityID && p.Fk_Pymn == pymnID && p.FK_control == true && p.tbMoalefeValueFish.Any(t=>t.FK_Moalefe== fkMoalfe &&t.mlfvlfsh_Month== month&&t.mlfvlfsh_Year==year));
                    if (excel == null)
                    {
                        excel = new tbmoalfefishexcel
                        {
                            Datatmie = DateTime.Now,
                            submitt = true,
                            Fk_Pymn = pymnID,
                            FK_control = true,
                            city = cityID,
                            usr_sabt = usr,
                            sabt = sabt
                        };
                        newExcels.Add(excel);
                        existingExcel.Add(excel); // اضافه به لیست برای حلقه بعدی
                    }
                    else
                    {
                        // بروزرسانی رکورد موجود
                        excel.Datatmie = DateTime.Now;
                        excel.submitt = true;
                        excel.sabt = sabt;
                    }
                }

                // ==== ذخیره Excel های جدید یکجا برای گرفتن ID ====
                if (newExcels.Any())
                {
                    db.tbmoalfefishexcel.AddRange(newExcels);
                    await db.SaveChangesAsync();
                }

                // ==== ایجاد یا بروزرسانی tbMoalefeValueFish ====
                foreach (var item in dataList)
                {
                    int cityID = System.Convert.ToInt32(item["CityID"]);
                    int pymnID = System.Convert.ToInt32(item["PymnID"]);
                    int idPersonal = System.Convert.ToInt32(item["IDPersonal"]);
                    int fkMoalfe = System.Convert.ToInt32(item["FkMoalfe"]);
                    decimal value = System.Convert.ToDecimal(item["value"]);

                    var excel = existingExcel.First(p => p.city == cityID && p.Fk_Pymn == pymnID);

                    // ریست Finalaccept رکوردهای قبلی
                    //var previousAccepts = excel.tbMoalefeValueFish
                    //    .Where(p => p.FK_Moalefe == fkMoalfe &&
                    //                p.FK_User == idPersonal &&
                    //                p.mlfvlfsh_Year == year &&
                    //                p.mlfvlfsh_Month == month &&
                    //                p.Finalaccept == true)
                    //    .ToList();
                    //previousAccepts.ForEach(p => p.Finalaccept = null);
                    var previousAccepts = await db.tbMoalefeValueFish
    .Where(p => 
                p.FK_Moalefe == fkMoalfe &&
                p.FK_User == idPersonal &&
                p.mlfvlfsh_Year == year &&
                p.mlfvlfsh_Month == month &&
                p.Finalaccept == true)
    .ToListAsync();

                    foreach (var p in previousAccepts)
                    {
                        p.Finalaccept = null;
                    }


                    //                    await db.Database.ExecuteSqlCommandAsync(@"
                    //UPDATE tbMoalefeValueFish
                    //SET Finalaccept = NULL
                    //WHERE FK_EXCel = @excel
                    //AND FK_Moalefe = @moalfe
                    //AND FK_User = @user
                    //AND mlfvlfsh_Year = @year
                    //AND mlfvlfsh_Month = @month
                    //AND Finalaccept = 1",
                    //new SqlParameter("@excel", excel.ID),
                    //new SqlParameter("@moalfe", fkMoalfe),
                    //new SqlParameter("@user", idPersonal),
                    //new SqlParameter("@year", year),
                    //new SqlParameter("@month", month));

                    // بررسی وجود رکورد
                    var fishRecord = excel.tbMoalefeValueFish
                        .FirstOrDefault(p => p.FK_Moalefe == fkMoalfe && p.FK_User == idPersonal &&
                                             p.mlfvlfsh_Year == year && p.mlfvlfsh_Month == month);

                    if (fishRecord != null)
                    {
                        fishRecord.submit = true;
                        fishRecord.Datatmie = DateTime.Now;
                        fishRecord.mlfvlfsh_Value = (double)value;
                        fishRecord.Finalaccept = true;
                    }
                    else
                    {
                        newFishItems.Add(new tbMoalefeValueFish
                        {
                            mlfvlfsh_Month = month,
                            mlfvlfsh_Year = year,
                            submit = true,
                            Datatmie = DateTime.Now,
                            FK_User = idPersonal,
                            FK_Moalefe = fkMoalfe,
                            FK_EXCel = excel.ID,
                            mlfvlfsh_Value = (double)value,
                            Finalaccept = true
                        });
                    }
                }

                // ==== درج همه رکوردهای جدید tbMoalefeValueFish یکجا ====
                if (newFishItems.Any())
                {
                    db.tbMoalefeValueFish.AddRange(newFishItems);
                }

                await db.SaveChangesAsync(); // ✅ فقط یک بار SaveChangesAsync
            }

            return Json(new { success = true });
        }






