        public async Task<ActionResult> viewmonthyearmahdodatmahdodatas33li(int month = 0, int year = 0, int id = 0)
        {
            int componentId = id;
            try
            {
                if (month == 0)
                {
                    month = 11;
                    year = 1403;
                }

                var currentUser = await GetAuthenticatedUserAsync();
                if (currentUser == null) return Content("dfsd");

                var mainComponent = await db.dbtarifmahdodayt1
                    .FirstOrDefaultAsync(p => p.FK_moalfe == componentId);
                if (mainComponent == null) return Content("dfsd");

                var response = new FunctionModel
                {
                    year = new year { MoalfeVal_Year = year, month = month },
                    tickmomahdodat = new List<tickmomahdodat>(),
                    mahdoday = new List<mahdoday>(),
                    mahdadatballla = new List<mahdadatballla>(),
                    namemoalfeh = mainComponent.tbContractMoalefeDastmozdi.md_Title
                };

                await PopulateComponentStatus(response, currentUser, month, year, componentId);
                await PopulateTeamMembersData(response, currentUser, month, year, componentId);

                return View("~/Areas/Contracts/Views/RegistrationAndConfirmationProcedures/viewmonthyearmahdodatmahdodatasli.cshtml", response);
            }
            catch (Exception ex)
            {
                // TODO: log ex
                return Content("dfsd");
            }
        }

        private async Task PopulateComponentStatus(FunctionModel model, tbUsers currentUser, int month, int year, int componentId)
        {
            var componentStatus = await db.dbtarifmahdodayt1
                .Where(it => it.FK_moalfe == componentId)
                .Select(it => new
                {
                    it.FK_moalfe,
                    it.tbContractMoalefeDastmozdi.md_Title,
                    it.tbContractMoalefeDastmozdi.tbUnitParameter.unt_Name
                })
                .FirstOrDefaultAsync();

            if (componentStatus == null) return;

            var statusQuery = await db.tbmoalfefishexcel
                .Where(p => p.tbMoalefeValueFish.Any(s =>
                            s.mlfvlfsh_Month == month &&
                            s.mlfvlfsh_Year == year &&
                            s.FK_Moalefe == componentId) &&
                            p.FK_control != null &&
                            p.usr_sabt == currentUser.usr_ID)
                .OrderByDescending(p => p.ID)
                .FirstOrDefaultAsync();

            int statusValue = 0;

            if (statusQuery != null)
            {
                if (statusQuery.tbMoalefeValueFish.Any(s => s.Finalaccept == true))
                    statusValue = 2;
                else if (statusQuery.sabtnahaei == true)
                    statusValue = 3;
                else
                    statusValue = 1;
            }

            model.tickmomahdodat.Add(new tickmomahdodat
            {
                IDMOalfeh = componentId,
                namemoalfeh = componentStatus.md_Title,
                nomoalfeh = componentStatus.unt_Name,
                value = statusValue
            });
        }

        private async Task PopulateTeamMembersData(FunctionModel model, tbUsers currentUser, int month, int year, int componentId)
        {
            var teamMemberIds = await db.tbAdamAdam
                .Where(p => p.Name == currentUser.usr_ID && p.Value == 1)
                .Select(p => p.nam)
                .ToListAsync();

            if (!teamMemberIds.Any()) return;

            var teamData = await (from user in db.tbUsers
                                  join position in db.dbtarifmahdodayt4 on user.usr_ID equals position.FK_usr
                                  join contract in db.Link_User_And_Peyman on user.usr_ID equals contract.FK_User_ID
                                  join city in db.tbCities on user.usr_City_Dutysystem equals city.ID
                                  join componentLimit in db.dbtarifmahdodayt2 on user.usr_ID equals componentLimit.FK_usr
                                  where teamMemberIds.Contains(user.usr_ID) &&
                                        position.Position == true &&
                                        contract.Status == true &&
                                        componentLimit.FK_moalfe == componentId
                                  select new
                                  {
                                      User = user,
                                      Position = position,
                                      Contract = contract,
                                      City = city,
                                      ComponentLimit = componentLimit
                                  }).ToListAsync();

            var performanceData = await db.tbMoadelPadashJarimeAyab
                .Where(p => teamMemberIds.Contains(p.UserID) && p.Month == month && p.Year == year)
                .ToDictionaryAsync(p => p.UserID, p => new { p.Moadel, p.AyabOZahab });

            var submittedValues = await (from excel in db.tbmoalfefishexcel
                                         join value in db.tbMoalefeValueFish on excel.ID equals value.FK_EXCel
                                         where teamMemberIds.Contains(value.FK_User) &&
                                               value.mlfvlfsh_Month == month &&
                                               value.mlfvlfsh_Year == year &&
                                               value.FK_Moalefe == componentId &&
                                               excel.FK_control != null
                                         select new
                                         {
                                             value.FK_User,
                                             value.mlfvlfsh_Value,
                                             value.Finalaccept,
                                             excel.usr_sabt
                                         }).ToListAsync();

            foreach (var member in teamData)
            {
                performanceData.TryGetValue(member.User.usr_ID, out var memberPerformance);
                double performance = memberPerformance?.Moadel ?? 0;

                var memberValue = submittedValues
                    .FirstOrDefault(v => v.FK_User == member.User.usr_ID &&
                                        (v.usr_sabt == currentUser.usr_ID || v.Finalaccept == true)) ??
                                  submittedValues.FirstOrDefault(v => v.FK_User == member.User.usr_ID);

                var limitData = new mahdoday
                {
                    PersonalID = (int)member.User.usr_Personal_ID,
                    fullnam = member.User.FullName,
                    IDpersonal = (int)member.User.usr_ID,
                    month = month,
                    year = year,
                    fkmoalfe = componentId,
                    bastehID = (int)member.Position.FK_name,
                    bastehname = member.Position.dbtarifmahdodayt3.name,
                    CITynam = member.City.Name,
                    cityID = (int)member.User.usr_City_Dutysystem,
                    PymnID = (int)member.Contract.FK_Peyman_ID,
                    pymanname = member.Contract.tbPeymanContracts.pec_Title,
                    seghf = (double)member.ComponentLimit.value,
                    moadel = performance,
                    value22 = (double)(memberValue?.mlfvlfsh_Value ?? 0)
                };

                var positionLimit = await db.dbtarifmahdodayt5
                    .FirstOrDefaultAsync(p =>
                        p.FK_marhal4 == member.Position.FK_name &&
                        p.FK_city == member.City.ID &&
                        p.FK_Pymn == member.Contract.FK_Peyman_ID &&
                        p.FK_moalf == componentId);

                if (positionLimit != null)
                {
                    limitData.seghfBasteh = (double)positionLimit.value;
                    limitData.seghfBastehID = positionLimit.ID;
                    limitData.IDtackBasteh = positionLimit.dbtarifmahdodayt3.ID;
                    limitData.nametackBasteh = positionLimit.dbtarifmahdodayt3.name;
                }

                model.mahdoday.Add(limitData);
            }
        }

        private async Task<tbUsers> GetAuthenticatedUserAsync()
        {
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null) return null;

            var nationalCode = Utility.Base64.Base64Decode(cookie_user.Value);
            return await db.tbUsers.FirstOrDefaultAsync(p => p.usr_NationalCode.ToString() == nationalCode);
        }
















