        public async Task<ActionResult> viewmonthyearmahdodatmahdodataslicreate111(List<Dictionary<string, object>> dataList)
        {
            try
            {
                if (dataList == null || !dataList.Any())
                {
                    return Json(new { success = false, message = "لیست داده‌ها خالی است." });
                }

                // استخراج سال و ماه از اولین آیتم
                int year2 = System.Convert.ToInt32(dataList[0]["Year"]);
                int mon = System.Convert.ToInt32(dataList[0]["Month"]);

                // استخراج کاربر از کوکی
                int usr = 0;
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user != null)
                {
                    var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                    using (SaabEntities db = new SaabEntities())
                    {
                        var User = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode.ToString() == nationalcode);
                        if (User != null)
                        {
                            usr = User.usr_ID;
                        }
                    }
                }

                List<tbMoalefeValueFish> newItems = new List<tbMoalefeValueFish>();

                using (SaabEntities db = new SaabEntities())
                {
                    foreach (var item in dataList)
                    {
                        // استخراج مقادیر
                        int cityID = System.Convert.ToInt32(item["CityID"]);
                        int pymnID = System.Convert.ToInt32(item["PymnID"]);
                        int year = System.Convert.ToInt32(item["Year"]);
                        int month = System.Convert.ToInt32(item["Month"]);
                        int idPersonal = System.Convert.ToInt32(item["IDPersonal"]);
                        int fkMoalfe = System.Convert.ToInt32(item["FkMoalfe"]);
                        decimal value = System.Convert.ToDecimal(item["value"]);
                        int sabt = System.Convert.ToInt32(item["sabt"]);

                        tbmoalfefishexcel savedfunctions;

                        // بررسی رکورد موجود در tbmoalfefishexcel
                        var findsavedfunctions = await db.tbmoalfefishexcel
                            .Where(p => p.usr_sabt == usr && p.del != true &&
                                        p.tbMoalefeValueFish.Any(s => s.mlfvlfsh_Month == month && s.mlfvlfsh_Year == year) &&
                                        p.Fk_Pymn == pymnID && p.FK_control == true && p.city == cityID)
                            .FirstOrDefaultAsync();

                        if (findsavedfunctions != null)
                        {
                            findsavedfunctions.Datatmie = DateTime.Now;
                            findsavedfunctions.sabt = sabt;
                            findsavedfunctions.submitt = true;
                            savedfunctions = findsavedfunctions;
                        }
                        else
                        {
                            savedfunctions = new tbmoalfefishexcel
                            {
                                Datatmie = DateTime.Now,
                                submitt = true,
                                Fk_Pymn = pymnID,
                                FK_control = true,
                                city = cityID,
                                usr_sabt = usr,
                                sabt = sabt
                            };
                            db.tbmoalfefishexcel.Add(savedfunctions);
                            await db.SaveChangesAsync(); // برای گرفتن ID
                        }

                        // ریست کردن Finalaccept رکوردهای قبلی
                        var findtbMoalefeValueFishaccept = await db.tbMoalefeValueFish
                            .Where(p => p.FK_Moalefe == fkMoalfe && p.FK_User == idPersonal &&
                                        p.mlfvlfsh_Year == year && p.mlfvlfsh_Month == month && p.Finalaccept == true)
                            .ToListAsync();

                        foreach (var t in findtbMoalefeValueFishaccept)
                        {
                            t.Finalaccept = null;
                        }

                        // بررسی رکورد موجود در tbMoalefeValueFish
                        var findtbMoalefeValueFish = await db.tbMoalefeValueFish
                            .Where(p => p.FK_EXCel == savedfunctions.ID && p.FK_Moalefe == fkMoalfe &&
                                        p.FK_User == idPersonal && p.mlfvlfsh_Year == year && p.mlfvlfsh_Month == month)
                            .FirstOrDefaultAsync();

                        if (findtbMoalefeValueFish != null) // ✅ ویرایش
                        {
                            findtbMoalefeValueFish.submit = true;
                            findtbMoalefeValueFish.Datatmie = DateTime.Now;
                            findtbMoalefeValueFish.mlfvlfsh_Value = (double)value;
                            findtbMoalefeValueFish.Finalaccept = true;
                        }
                        else // ✅ درج
                        {
                            var tbMoalefeValueFish2 = new tbMoalefeValueFish
                            {
                                mlfvlfsh_Month = month,
                                mlfvlfsh_Year = year,
                                submit = true,
                                Datatmie = DateTime.Now,
                                FK_User = idPersonal,
                                FK_Moalefe = fkMoalfe,
                                FK_EXCel = savedfunctions.ID,
                                mlfvlfsh_Value = (double)value,
                                Finalaccept = true
                            };
                            newItems.Add(tbMoalefeValueFish2);
                        }
                    }

                    // درج همه رکوردهای جدید یکجا
                    if (newItems.Any())
                        db.tbMoalefeValueFish.AddRange(newItems);

                    await db.SaveChangesAsync();
                }

                return Json(new { success = true }); // ✅ پاسخ موفق
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = "خطا: " + ex.Message });
            }
        }





        public async Task<ActionResult> viewmonthyearmahdodatmahdodatasliforkenarsafhe(int month = 0, int year = 0, int id = 0)
        {
            try
            {
                if (month == 0)
                {
                    month = 1;
                    year = 1404;
                }

                var model = new FunctionModel
                {
                    tickmomahdodatkenar = new List<tickmomahdodatkenar>(),
                    tickmomahdodatkenar2 = new List<tickmomahdodatkenar2>(),
                    tickmomahdodat = new List<tickmomahdodat>(),
                    mahdoday = new List<mahdoday>(),
                    mahdadatballla = new List<mahdadatballla>()
                };

                // ===== resolve moalefe id =====
                int idd = await db.tbmarahlsabtbastedit6
                    .AsNoTracking()
                    .Where(p => p.FK_moalfeh2 == id)
                    .Select(x => (int?)x.FK_moalfe)
                    .FirstOrDefaultAsync() ?? id;

                // ===== login user =====
                var cookie = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie == null) return View(model);

                var phone = Utility.Base64.Base64Decode(cookie.Value);

                var loginUserId = await db.tbUsers
                    .AsNoTracking()
                    .Where(p => p.usr_NationalCode.ToString() == phone)
                    .Select(x => x.usr_ID)
                    .FirstOrDefaultAsync();

                if (loginUserId == 0) return View(model);

                // ===== managed users =====
                var managedIds = await db.tbAdamAdam
                    .AsNoTracking()
                    .Where(x => x.Name == loginUserId && x.Value == 1)
                    .Select(x => x.nam)
                    .ToListAsync();

                if (!managedIds.Any()) return View(model);

                // ===== tarif1 =====
                var tarif1 = await db.dbtarifmahdodayt1
                    .AsNoTracking()
                    .Where(x => x.FK_moalfe == id)
                    .Select(x => new
                    {
                        x.ID,
                        Title = x.tbContractMoalefeDastmozdi.md_Title
                    })
                    .FirstOrDefaultAsync();

                if (tarif1 == null) return View(model);

                model.idmaolfeh = id;
                model.namemoalfeh = tarif1.Title;

                // ===== preload dictionaries =====

                var users = await db.tbUsers
                    .AsNoTracking()
                    .Where(x => managedIds.Contains(x.usr_ID))
                    .Select(x => new
                    {
                        x.usr_ID,
                        x.usr_City_Dutysystem
                    })
                    .ToListAsync();

                //var bastDict = await db.dbtarifmahdodayt4
                //    .AsNoTracking()
                //    .Where(x => managedIds.Contains(x.FK_usr) && x.Position == true)
                //    .ToDictionaryAsync(x => x.FK_usr, x => x.FK_name);
                var bastDict = await db.dbtarifmahdodayt4
    .AsNoTracking()
    .Where(x => managedIds.Contains(x.FK_usr) && x.Position == true)
    .GroupBy(x => x.FK_usr)
    .ToDictionaryAsync(g => g.Key, g => g.FirstOrDefault().FK_name);
                var peymanDict = await db.Link_User_And_Peyman
                    .AsNoTracking()
                    .Where(x => managedIds.Contains(x.FK_User_ID) && x.Status == true)
                    .GroupBy(x => x.FK_User_ID)
                    .ToDictionaryAsync(
                        g => g.Key,
                        g => g.First().FK_Peyman_ID
                    );


                var cityDict = await db.tbCities
                    .AsNoTracking()
                    .ToDictionaryAsync(x => x.ID, x => x.Name);

                // ===== tarif5 lookup =====

                var tarif5List = await db.dbtarifmahdodayt5
                    .AsNoTracking()
                    .Where(x => x.FK_moalf == tarif1.ID)
                    .Select(x => new
                    {
                        x.FK_marhal4,
                        x.FK_city,
                        x.FK_Pymn,
                        x.value,
                        BastID = x.dbtarifmahdodayt3.ID,
                        BastName = x.dbtarifmahdodayt3.name
                    })
                    .ToListAsync();

                var tarif5Lookup = tarif5List.ToDictionary(
                    x => (x.FK_marhal4, x.FK_city, x.FK_Pymn),
                    x => x);

                // ===== main fast loop =====

                foreach (var u in users)
                {
                    if (!bastDict.TryGetValue(u.usr_ID, out var bast)) continue;
                    if (!peymanDict.TryGetValue(u.usr_ID, out var pymn)) continue;

                    int city = u.usr_City_Dutysystem ?? 0;

                    if (tarif5Lookup.TryGetValue((bast, city, pymn), out var t5))
                    {
                        model.tickmomahdodatkenar2.Add(new tickmomahdodatkenar2
                        {
                            IDMOalfeh = t5.BastID,
                            IDBasteh = t5.BastID,
                            namemoalfeh = t5.BastName,
                            value = (double)t5.value
                        });
                    }
                }

                // ===== grouping + average =====

                model.tickmomahdodatkenar = model.tickmomahdodatkenar2
                    .GroupBy(x => x.IDBasteh)
                    .Select(g => new tickmomahdodatkenar
                    {
                        IDBasteh = g.Key,
                        namebasteh = g.First().namemoalfeh,
                        value = g.Average(x => x.value)
                    })
                    .ToList();

                return View(
                    "~/Areas/Contracts/Views/RegistrationAndConfirmationProcedures/viewmonthyearmahdodatmahdodatasliforkenarsafhe.cshtml",
                    model);
            }
        catch(Exception ex)
            {
                return Content (ex.Message);
            }
        }


