        public ActionResult listselectorviewsabtnew()
        {
            FunctionModel lstMoalefeexcel2 = new FunctionModel();
            lstMoalefeexcel2.MarhaleViewModel = new List<MarhaleViewModel>();
            List<tbmarahesabt4> listtbmarahesabt4 = new List<tbmarahesabt4>();
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user != null)
            {
                var phone = Utility.Base64.Base64Decode(cookie_user.Value);
                using (SaabEntities db = new SaabEntities())
                {
                    try
                    {
                        var User = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode != null && p.usr_NationalCode.ToString() == phone);
                        if (User != null)
                        {

                            listtbmarahesabt4 = db.tbmarahesabt4.Where(p => p.FK_usr == User.usr_ID && p.del != true).ToList();
                            foreach(var item in listtbmarahesabt4)
                            {
                                if (item.sabt == true)
                                {
                                    var MarhaleViewModel = new MarhaleViewModel
                                    {
                                        ID = item.ID,
                                        PeymanTitle = item.tbmarahlsabtbastedit2.tbPeymanContracts.pec_Title,
                                        CityName = item.tbmarahlsabtbastedit2.tbCities.Name,
                                        Naem = item.tbmarahlsabtbastedit2.tbmarahlsabtbastedit1.naem,
                                        Number = (int)item.number,
                                      
                                        vaziat="ثبت"
                                    };
                                    lstMoalefeexcel2.MarhaleViewModel.Add(MarhaleViewModel);
                                }
                                else if (item.control == true)
                                {
                                    var MarhaleViewModel = new MarhaleViewModel
                                    {
                                        ID = item.ID,
                                        PeymanTitle = item.tbmarahlsabtbastedit2.tbPeymanContracts.pec_Title,
                                        CityName = item.tbmarahlsabtbastedit2.tbCities.Name,
                                        Naem = item.tbmarahlsabtbastedit2.tbmarahlsabtbastedit1.naem,
                                        Number = (int)item.number,
                              
                                        vaziat = "کنترل"
                                    };
                                    lstMoalefeexcel2.MarhaleViewModel.Add(MarhaleViewModel);
                                }
                                else
                                {
                                    var MarhaleViewModel = new MarhaleViewModel
                                    {
                                        ID = item.ID,
                                        PeymanTitle = item.tbmarahlsabtbastedit2.tbPeymanContracts.pec_Title,
                                        CityName = item.tbmarahlsabtbastedit2.tbCities.Name,
                                        Naem = item.tbmarahlsabtbastedit2.tbmarahlsabtbastedit1.naem,
                                        Number = (int)item.number,
                                        
                                        vaziat = "تایید"
                                    };
                                    lstMoalefeexcel2.MarhaleViewModel.Add(MarhaleViewModel);
                                }
                              
                            }
          
                        }
                    }
                    catch (Exception ex)
                    {
                    }

                }
            }
            return View("~/Areas/Contracts/Views/RegistrationAndConfirmationProcedures/listselectorviewsabtnew.cshtml", lstMoalefeexcel2);

        }

