        public string authorizedUsers_Edit(List<SaabWebProject.Models.DomainModels.tbReffrenceSaveLevelUser> things)
        {
            try
            {
                using (DbContextTransaction transaction = db.Database.BeginTransaction())
                {
                    try
                    {
                        var ff = things.FirstOrDefault().FK_LevelID;
                        var olds = db.tbReffrenceSaveLevelUser.Where(p => p.FK_LevelID == ff).ToList();
                        if (olds != null)
                            db.tbReffrenceSaveLevelUser.RemoveRange(olds);
                        db.tbReffrenceSaveLevelUser.AddRange(things);
                        db.SaveChanges();

                        transaction.Commit();
                        return "True";
                    }
                    catch (Exception ex)
                    {
                        transaction.Rollback();
                        return ex.Message;
                    }
                }

            }
            catch (Exception ex)
            {

                return "false";
            }
        }
