        /// <summary>
        /// نمایش هشدار برای ثبت عملکرد ها
        /// </summary>
        /// <returns></returns>
        /// 
        [AuthorizeAAA]
        public ActionResult ReffrenceSaveWarningToUser()
        {
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user != null)
            {
                var phone = Utility.Base64.Base64Decode(cookie_user.Value);
                using (SaabEntities db = new SaabEntities())
                {
                    try
                    {
                        var User = db.tbUsers.Where(p => p.usr_NationalCode.ToString() == phone).FirstOrDefault();
                        if (User != null)
                        {
                            return PartialView(rep_reffrenceSave.GetUserWarning(User.usr_ID));
                        }
                        else
                        {
                            return PartialView(new tbReffrenceSaveLevel());
                        }
                    }
                    catch (Exception)
                    {

                        return PartialView(new tbReffrenceSaveLevel());
                    }

                }
            }
            else
            {
                return PartialView(new tbReffrenceSaveLevel());
            }
        }
        /// <summary>
        /// دریافت پیمان هایی که روز ثبت آن ها برای این کاربر فرارسیده است
        /// </summary>
        /// <param name="user_id"></param>
        /// <param name="isSabt"></param>
        /// <returns></returns>
        /// 
        [AuthorizeAAA]
        public ActionResult ReffrenceSaveGetPeymans(string user_id = "Admin", bool isSabt = false, int IsFor = 0)
        {
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user != null)
            {
                var phone = Base64.Base64Decode(cookie_user.Value);
                using (SaabEntities db = new SaabEntities())
                {
                    var User = db.tbUsers.Where(p => p.usr_NationalCode.ToString() == phone).FirstOrDefault();
                    if (User != null)
                    {
                        if (IsFor == 1)
                        {
                            return View("~/Areas/Contracts/Views/RegistrationAndConfirmationProcedures/ReffrenceSaveGetPeymans.cshtml", rep_reffrenceSave.GetUserPeymans(User.usr_ID, isSabt, IsFor));
                        }
                        else
                        {

                            var a = rep_reffrenceSave.GetUserPeymans(User.usr_ID, isSabt, IsFor);
                            List<tbReffrenceSave> aa = new List<tbReffrenceSave>();
                            foreach (var item in a)
                            {
                                aa.Add(item);
                            }
                            return View("~/Areas/Contracts/Views/Peyman/_GetAllListPeymans_SingleSelectfor.cshtml", aa);
                        }
                    }
                }
            }
            return View("~/Areas/Contracts/Views/RegistrationAndConfirmationProcedures/ReffrenceSaveGetPeymans.cshtml", new List<tbReffrenceSave>());
        }







