        [AuthorizeAAA]
        public string SaveReffrenceSave(tbReffrenceSave Total)
        {
            if (Total.ID != 0)
            {
                using (var db = new SaabEntities())
                {
                    var x = db.tbReffrenceSave.Where(p => p.IsFor == Total.IsFor && p.FK_PeymanID == Total.FK_PeymanID).FirstOrDefault();
                    if (db.tbReffrenceSave.Where(p => p.IsFor == Total.IsFor && p.FK_PeymanID == Total.FK_PeymanID).FirstOrDefault() == null)
                    {
                        var result = rep_reffrenceSave.Create(Total);
                        return result;
                    }
                    else
                    {
                        Total.ID = x.ID;
                        var result = rep_reffrenceSave.Update(Total);
                        return result;
                    }
                }
            }
            else
            {
                var result = rep_reffrenceSave.Create(Total);
                return result;
            }

        }

