        [AuthorizeAAA]
        public List<tbReffrenceSaveLevel> ReffrenceAccept_GetThisUserBasteForList()
        {
            List<tbReffrenceSaveLevel> obj = new List<tbReffrenceSaveLevel>();

            var day = DateTime.Now.GetShamsiDayOfMonth();

            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user != null)
            {
                var phone = Utility.Base64.Base64Decode(cookie_user.Value);
                using (SaabEntities db = new SaabEntities())
                {
                    try
                    {
                        var User = db.tbUsers.Where(p => p.usr_NationalCode.ToString() == phone).FirstOrDefault();
                        if (User != null)
                        {
                            var rr = db.tbReffrenceAcceptLevelUsers.Where(p => p.FK_User == User.usr_ID).ToList();
                            foreach (var item in rr)
                            {
                                var startDay = item.tbReffrenceAcceptLevel.StartDayInMonth;
                                var endday = startDay + (item.tbReffrenceAcceptLevel.Duration);

                                if (day >= startDay && day <= endday)
                                {
                                    obj.Add(item.tbReffrenceAcceptLevel.tbReffrenceAccept.tbReffrenceSaveLevel);
                                }
                            }
                            return obj; // میرد برای اوردن مدارک ثبت شده در بازه زمانی مشخص
                        }



                    }
                    catch (Exception)
                    {

                        return obj;
                    }

                }
            }
            else
            {
                return obj;
            }


            return obj;
        }
